const paths={code:'m8 6-6 6 6 6m8-12 6 6-6 6M14 3l-4 18',home:'M3 11 12 3l9 8 M5 10v11h14V10 M10 21v-7h4v7',library:'M5 3h10l5 5v13H5Z M15 3v6h5 M8 13h8 M8 17h6',logo:'M5 8 12 4l7 4v8l-7 4-7-4Z M8 9l4-2 4 2-4 2Z',practice:'M12 3v8l5-3 M19 8a8 8 0 1 1-9-4 M8 12a4 4 0 1 0 7-3',test:'M3 6h18v12H3Z M6 9h1m3 0h1m3 0h1m3 0h1 M6 12h1m3 0h1m3 0h1m3 0h1 M7 15h10',lessons:'M12 6v15 M12 6Q7 3 3 5v14q5-2 9 2 M12 6q5-3 9-1v14q-5-2-9 2',stats:'M4 19V5 M4 19h17 M8 16v-5 M13 16V8 M18 16V4',records:'m3 7 4 4 5-7 5 7 4-4-2 11H5Z M5 21h14',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M10 3h4l1 3 3 1 3 2v4l-3 1-1 3-2 3h-4l-1-3-3-1-3-2v-4l3-1 1-3Z',help:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M9.5 9a2.5 2.5 0 1 1 4.5 1.5L12 13 M12 16h.01',theme:'M4 3h6v17H4Z M10 7h6v13h-6 M16 12h5v8h-5 M7 16h.01',globe:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M3 12h18 M12 3q8 9 0 18-8-9 0-18',user:'M12 4a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M5 21v-2a7 7 0 0 1 14 0v2',restart:'M4 10a8 8 0 1 1 1 8 M4 4v6h6',close:'m6 6 12 12 M6 18 18 6',arrow:'M4 12h16 M14 6l6 6-6 6',speed:'M4 18a9 9 0 1 1 16 0 M12 13l5-5 M5 18h14',target:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10 M12 10v4 M10 12h4',daily:'M12 3v8l6-3 M20 10a8 8 0 1 1-11-6',check:'m5 12 4 4 10-10',pause:'M8 5v14 M16 5v14',play:'m7 4 13 8-13 8Z',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5'};
