let disconnectLessonMap=()=>{},disconnectHomeDemo=()=>{};
const previousLessonMaterials=new Map();
function variedLesson(info){let words;const previous=previousLessonMaterials.get(info.id);for(let tries=0;tries<8;tries++){words=lessonWords(info,settings.language);if(words.join(' ')!==previous)break;}previousLessonMaterials.set(info.id,words.join(' '));return words;}
let activityPayload=null,hintUntil=0,codeTrack=settings.codeTrack;
let p=()=>progressFor(data,settings.language,settings.layouts[settings.language]),layout=()=>settings.layouts[settings.language],language=()=>LANGUAGES[settings.language];
const coach=createCoach({getData:()=>data,persist,render,navigate,toast,openDialog,startActivity,startLesson:(group,step)=>{context={group,step};view='lesson';location.hash='lessons';render()},replaceData:value=>{data=ensureLearning(value);settings={...DEFAULT_SETTINGS,...data.settings,layouts:{...DEFAULT_SETTINGS.layouts,...data.settings.layouts}};data.settings=settings;persist({replace:true});applySettings()}});
const onboarding=createOnboarding({onTypingKey:playTypingKey,onTypingFocus:()=>typingAudio.prime(),onTypingBlur:()=>typingAudio.stop(),getData:()=>data,persist,openDialog,closeDialog,launch:(path,lang,selectedLayout)=>{
 settings.language=lang;settings.layouts[lang]=availableLayouts(lang).includes(selectedLayout)?selectedLayout:LANGUAGES[lang].layout;
 forcedFocus=null;activityPayload=null;
 if(path==='lesson'){context={group:0,step:0};view='lesson';location.hash='lessons';render();}
 else navigate(path==='code'?'code':'practice');
}});
let previewDialog=null,suppressPreviewFocus=false;
const sessionPreview=createSessionPreview({
 onShow:owned=>{
  if(session!==owned)return;
  previewDialog=document.createElement('dialog');previewDialog.className='session-preview';
  const code=!!context.codeLines,text=code?context.codeLines.map(line=>' '.repeat(line.indent)+line.words.join(' ')).join('\n'):owned.words.join(' ');
  previewDialog.innerHTML=`<div class="preview-heading"><span>${code?'Фрагмент кода':'Текст задания'} · ${owned.words.length} ${wordLabel(owned.words.length)}</span><b>Сначала взгляни на текст</b></div><pre class="preview-text ${code?'preview-code':''}">${esc(text)}</pre><div class="preview-footer"><span>Набор начнётся через 2 секунды</span><button type="button">Отмена <kbd>Esc</kbd></button></div><div class="preview-time" aria-hidden="true"></div>`;
  previewDialog.addEventListener('cancel',e=>{e.preventDefault();sessionPreview.cancel()});
  previewDialog.querySelector('button').addEventListener('click',()=>sessionPreview.cancel());
  if(code){const longest=Math.max(...text.split('\n').map(line=>line.length)),rows=text.split('\n').length;previewDialog.querySelector('pre').style.fontSize=Math.min(settings.fontSize,23,Math.max(14,(Math.min(920,innerWidth-80)-70)/(longest*.62)),Math.max(14,(innerHeight-250)/(rows*1.55)))+'px';}
  document.body.append(previewDialog);previewDialog.showModal();
 },
 onHide:()=>{if(!previewDialog)return;suppressPreviewFocus=true;previewDialog.remove();previewDialog=null;$('typingInput')?.blur();focused=false;queueMicrotask(()=>suppressPreviewFocus=false);},
 onReady:owned=>{if(session!==owned||document.hidden)return;typingAudio.prime();focused=true;owned.resume();$('typingInput')?.focus({preventScroll:true});paint();}
});
function startActivity(words,ctx){activityPayload={words,ctx};view='activity';location.hash='activity';render()}
function requestHint(){if(!session||session.status==='finished')return;session.hint();hintUntil=performance.now()+3000;paint();$('typingInput')?.focus({preventScroll:true})}
function keyboardSettings(){return {...settings,hintMode:context?.hideHints?'request':settings.hintMode,reveal:performance.now()<hintUntil}}
function todayProgress(progress=p(),lang=settings.language,selectedLayout=layout()){return dailyProgress({history:[...progress.history.filter(r=>!r.metricsVersion||r.metricsVersion<3),...learningFor(data,lang,selectedLayout).activities]})}
function storageError(){toast('Не удалось сохранить прогресс. Результат остаётся на экране: скачай копию или повтори сохранение.');}
function persist(options){return progressStore.save(options).catch(()=>{storageError();return false})}
function toast(message){clearTimeout(toastTimer);$('toast').textContent=message;$('toast').classList.add('show');toastTimer=setTimeout(()=>$('toast').classList.remove('show'),4500)}
function speed(cpm){let v=settings.unit==='wpm'?cpm/5:settings.unit==='cps'?cpm/60:cpm;return Number.isFinite(v)?v.toFixed(settings.unit==='cpm'?0:1):'—'}
const unit=()=>settings.unit.toUpperCase();
function formatDuration(ms){if(ms>0&&ms<1000)return (ms/1000).toFixed(1)+'с';let sec=Math.max(0,Math.round(ms/1000));return `${Math.floor(sec/60)}:${String(sec%60).padStart(2,'0')}`}
function wordLabel(n){return n%10===1&&n%100!==11?'слово':n%10>=2&&n%10<=4&&(n%100<12||n%100>14)?'слова':'слов'}
function lineLabel(n){return n%10===1&&n%100!==11?'строка':n%10>=2&&n%10<=4&&(n%100<12||n%100>14)?'строки':'строк'}
function date(at){return new Date(at).toLocaleString('ru-RU',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})}
function applySettings(){typingAudio.sync();document.documentElement.style.setProperty('--switch-color',SWITCHES[settings.keyboardSwitch]?.color||SWITCHES.mac.color);document.body.dataset.theme=settings.theme;document.documentElement.style.setProperty('--type-size',settings.fontSize+'px');document.documentElement.style.setProperty('--letter-spacing',(settings.letterSpacing||0)+'px');document.body.classList.toggle('reverse',settings.reverse);for(let c of ['line','block','underline'])document.body.classList.toggle('caret-'+c,settings.caretStyle===c);document.documentElement.style.setProperty('--caret-duration',({off:'0s',slow:'.3s',medium:'.15s',fast:'.07s'})[settings.caretSpeed]||'.15s')}
