 $('sidebar').innerHTML=`<button class="logo" data-view="home" aria-label="Десять пальцев — главная"><span class="brand-symbol">&lt;/&gt;</span><span class="brand-copy">Десять пальцев<small>DEV EDITION</small></span></button><div class="nav-section">WORKSPACE</div>${items.map(([id,name,number])=>`<button class="nav-button ${view===id||(view==='lesson'&&id==='lessons')||(view==='activity'&&id==='library')?'active':''}" data-view="${id}" aria-label="${name}" title="${name}" ${view===id?'aria-current="page"':''}>${icon(id)}<span>${name}</span><small class="nav-number">${number}</small></button>`).join('')}<div class="nav-spacer"></div><div class="sidebar-note"><span class="status-dot"></span> Скорость для разработки<small>Точность → ритм → скорость</small></div><button class="nav-button nav-secondary" data-action="themes" aria-label="Цвета" title="Цвета">${icon('theme')}<span>Цвета</span></button><button class="nav-button ${view==='settings'?'active':''}" data-view="settings" aria-label="Настройки" title="Настройки">${icon('settings')}<span>Настройки</span></button><button class="nav-button nav-secondary" data-action="onboarding" aria-label="Обучение" title="Обучение">${icon('play')}<span>Обучение</span></button><button class="nav-button nav-secondary" data-action="help" aria-label="Справка" title="Справка">${icon('help')}<span>Справка</span></button><div class="version">Десять пальцев <span>v5.9</span></div>`;
