 $('header').innerHTML=`<div class="header-location"><span class="workspace-path">~/typing<span>/</span></span><h1>${esc(titles[view])}</h1></div><div class="header-right"><div class="language-switch" role="group" aria-label="Язык набора">${[['ru','RU'],['en','EN']].map(([id,label])=>`<button data-training-language="${id}" class="${settings.language===id?'active':''}" aria-label="${id==='ru'?'Русский язык для печати':'Английский язык для печати'}" aria-pressed="${settings.language===id}">${label}</button>`).join('')}</div>${settings.language==='fr'?'<button class="soft-button" data-action="language">FR</button>':''}<button class="profile-button" data-view="stats" title="Личная статистика">${icon('stats')}<span>Прогресс</span></button><button class="icon-button mobile-help" data-action="help" aria-label="Как учиться" title="Как учиться">${icon('help')}</button></div><div class="workspace-tabs" aria-label="Быстрые разделы"><button data-view="practice" class="${view==='practice'?'active':''}" ${view==='practice'?'aria-current="page"':''}><span class="file-mark text-file">Aa</span>practice.txt</button><button data-view="code" class="${view==='code'?'active':''}" ${view==='code'?'aria-current="page"':''}><span class="file-mark code-file">{ }</span>${view==='code'?esc(files.code):'playground.js'}</button><span class="current-file">${!['practice','code'].includes(view)?esc(files[view]):esc(LAYOUTS[layout()].name)}</span></div>`;
 if($('footerProfile'))$('footerProfile').textContent=language().code+' · '+LAYOUTS[layout()].name;
