 return `<div class="workspace-heading code-heading"><div><p class="eyebrow">// DEVELOPER PRACTICE</p><h2>Код. С клавиатуры.</h2><p>Разные задачи и имена переменных. Новый текст — новый пример.</p></div><span class="profile-badge">EN<span>${esc(LAYOUTS[layout()].name)}</span></span></div><div class="code-tracks" role="group" aria-label="Материал для программистов">${Object.entries(CODE_TRACKS).map(([id,item])=>`<button data-code-track="${id}" class="code-track ${id===codeTrack?'active':''}" aria-label="${esc(item.name)}" aria-pressed="${id===codeTrack}"><span class="track-mark track-${id}">${esc(item.mark)}</span>${esc(item.name)}</button>`).join('')}</div><div class="code-volume-bar"><span>Объём задания</span><div role="group" aria-label="Объём кода">${Object.entries(CODE_VOLUMES).map(([id,option])=>`<button data-code-volume="${id}" class="${settings.codeVolume===id?'selected':''}" aria-pressed="${settings.codeVolume===id}">${option.name}<small>${option.min}–${option.max} слов</small></button>`).join('')}</div><small>${context.codeLines.length} ${lineLabel(context.codeLines.length)} · ${session.words.length} ${wordLabel(session.words.length)}</small></div><div class="code-brief"><div><strong>${esc(context.title)}</strong><p>${esc(track.description)}</p></div><button class="outline-button" data-view="library">Свой код →</button></div><p class="material-note">Отступы расставлены автоматически. Пробел — следующее слово, Enter — следующая строка. Все буквы и знаки · английская раскладка. Для постепенного изучения букв выбери <button data-start-language="en">English в практике →</button></p>`;
