 return `<section class="exercise ${code?'code-exercise':''}" aria-label="Упражнение"><div class="editor-surface"><div class="focus-controls" aria-label="Управление набором"><span>Спокойно набирай текст</span><button data-action="exit-focus" aria-label="Выйти из режима набора">${icon('pause')}Пауза / выйти <kbd>Esc</kbd></button></div><div class="editor-toolbar"><span class="editor-tab"><span class="file-mark ${code?'code-file':'text-file'}">${code?'{ }':'Aa'}</span>${file}</span><span class="editor-mode">${code?'CODE':'WORDS'} · ${language().code}</span><button class="icon-button" data-action="regenerate" aria-label="Новое упражнение в редакторе" title="Новое упражнение">${icon('restart')}</button></div><div id="sessionArea"><div class="stage unfocused" id="stage"><div class="stage-meta"><div class="stage-progress"><i id="exerciseProgress" style="width:0%"></i></div><span id="liveMetric"></span><span class="stage-count" id="stageCount"></span></div><div class="line-gutter" aria-hidden="true"><span>01</span><span>02</span><span>03</span></div><div id="caretOverlay" aria-hidden="true"></div><div class="words" id="words" aria-hidden="true"></div><button class="start-overlay" id="startOverlay">${icon('play')}<span id="startLabel">Нажмите, чтобы начать</span></button><textarea id="typingInput" class="typing-input ${settings.inputVisible?'visible':''}" aria-label="Ввод упражнения" autocomplete="off" autocapitalize="off" spellcheck="false" rows="1"></textarea></div><p class="input-message" id="inputMessage" role="status"></p><div class="exercise-actions"><button data-action="hint" title="Помощь · F1">${icon('help')}<span>подсказка</span><kbd>F1</kbd></button><button data-action="pause" title="Пауза">${icon('pause')}<span id="pauseActionLabel">пауза</span><kbd>Esc</kbd></button><button data-action="repeat">${icon('restart')}повторить</button><button data-action="regenerate">${icon('arrow')}${view==='activity'&&!['letters','shift','numbers','work'].includes(context.activity)?'выбрать текст':'новый текст'}</button></div></div><div class="editor-status"><span id="sessionState" class="session-state"><i class="status-dot"></i>READY</span><span>${code?'Пробел → слово · Enter → строка':'Пробел → слово'} <span class="status-divider">/</span> Backspace → исправить</span><span>${session.words.length} ${wordLabel(session.words.length)}</span></div></div>${keyboardMarkup(layout(),settings)}</section>`;
