function testControls(){
 const quote=settings.testMode==='quote',plain=!settings.numbers&&!settings.punctuation;
 return `<section class="control-panel test-controls" aria-label="Настройки теста"><div class="test-mode-row"><div class="segmented" role="group" aria-label="Режим теста">${[['words','По словам'],['time','По времени'],['quote','Цитата']].map(([v,n])=>`<button data-test-mode="${v}" class="${settings.testMode===v?'active':''}" aria-pressed="${settings.testMode===v}">${n}</button>`).join('')}</div>${quote?'':`<div class="segmented" role="group" aria-label="${settings.testMode==='time'?'Продолжительность':'Количество слов'}">${(settings.testMode==='time'?[15,30,60,120]:[10,25,50,100]).map(n=>`<button data-test-amount="${n}" class="${n===(settings.testMode==='time'?settings.testTime:settings.testWords)?'active':''}" aria-pressed="${n===(settings.testMode==='time'?settings.testTime:settings.testWords)}">${settings.testMode==='time'?n<60?n+'с':n/60+'м':n}</button>`).join('')}<button data-action="custom-test" title="Своё значение" aria-label="Своё значение">${![15,30,60,120].includes(settings.testTime)&&settings.testMode==='time'?esc(settings.testTime)+'с':settings.testMode==='words'&&![10,25,50,100].includes(settings.testWords)?esc(settings.testWords):'…'}</button></div>`}<button class="soft-button" data-action="language">${icon('globe')}${language().name}</button></div>${quote?'<p class="test-content-note">Готовый текст: регистр и знаки автора сохранены.</p>':`<div class="test-content-row"><span>Состав текста</span><div class="segmented" role="group" aria-label="Состав текста теста"><button data-action="test-plain" class="${plain?'active':''}" aria-pressed="${plain}">Только слова</button><button data-action="numbers" class="${settings.numbers?'active':''}" aria-label="Добавлять цифры" aria-pressed="${settings.numbers}"><span class="test-option-symbol" aria-hidden="true">123</span>Цифры</button><button data-action="punctuation" class="${settings.punctuation?'active':''}" aria-label="Добавлять знаки" aria-pressed="${settings.punctuation}"><span class="test-option-symbol" aria-hidden="true">.,!?</span>Знаки</button></div></div><p class="test-content-note">${testContentLabel(settings)}. Цифры и знаки можно включать отдельно.</p>`}</section>`;
}
function makeSession(words,ctx){wordView?.destroy();wordView=null;context={...ctx,lang:settings.language,layout:layout(),rules:{spaceToFinish:settings.spaceToFinish,noWayBack:settings.noWayBack,speedGoal:settings.speedGoal}};finishedHandled=false;focused=false;session=new TypingSession(words,{mode:ctx.mode||'words',seconds:ctx.seconds||0,spaceToFinish:settings.spaceToFinish,noWayBack:settings.noWayBack,strictTest:!!ctx.strictTest||ctx.kind==='test'});hintUntil=0;sessionPreview.reset(session);}
function render(){sessionPreview.reset(null);disconnectLessonMap();disconnectHomeDemo();codeTrack=settings.codeTrack;typingAudio.stop();if(view==='code'&&settings.language!=='en'){settings.language='en';forcedFocus=null;persist();}wordView?.destroy();wordView=null;document.body.classList.remove('typing-focus','session-active');nav();header();applySettings();if(view==='activity'&&activityPayload){makeSession(activityPayload.words,{kind:'activity',...activityPayload.ctx});header();$('content').innerHTML=`<div class="session-meta"><button class="soft-button" data-view="library">← Тексты</button><strong>${esc(context.title)}</strong><span>${language().code} · ${esc(LAYOUTS[layout()].name)}</span></div><div class="help-tip">${esc(context.reason||'')}</div>`+exerciseMarkup();bindSession()}else if(view==='practice'){let chars=[...language().alphabet].slice(0,p().unlocked).join('');let material=practiceMaterial(settings.language,chars,forcedFocus||targetLetter(p(),settings.language,settings.speedGoal));makeSession(material.words,{kind:'practice',material:material.type,materialVersion:5});$('content').innerHTML=panelMarkup()+`<p class="material-note">${material.type==='drill'?'Сочетания клавиш: с этим набором ещё нет слов.':esc(material.note)}</p>`+exerciseMarkup();bindSession()}else if(view==='code'){const item=codeExercise(codeTrack,materialRotation.pick('code-v4-'+codeTrack+'-'+settings.codeVolume,CODE_VARIANTS,[],10),settings.codeVolume);makeSession(item.words,{kind:'activity',activity:'code',codeTrack,codeLines:item.lines,title:item.title,contentId:'code-'+codeTrack+'-'+item.index+'-'+item.volume,reason:CODE_TRACKS[codeTrack].description});header();$('content').innerHTML=codeControls()+exerciseMarkup();bindSession()}else if(view==='test'){let words=settings.testMode==='quote'?language().quotes[Math.floor(Math.random()*language().quotes.length)].split(' '):generateTestWords({lang:settings.language,count:settings.testMode==='time'?Math.max(400,Math.min(10000,settings.testTime*12)):settings.testWords,numbers:settings.numbers,punctuation:settings.punctuation});makeSession(words,{kind:'test',mode:settings.testMode==='time'?'time':'words',testMode:settings.testMode,seconds:settings.testMode==='time'?settings.testTime:0,wordLimit:settings.testWords,numbers:settings.testMode!=='quote'&&settings.numbers,punctuation:settings.testMode!=='quote'&&settings.punctuation});$('content').innerHTML=testControls()+exerciseMarkup();bindSession()}else if(view==='lesson'){let info=lessonInfo(context.group,context.step,layout());makeSession(variedLesson(info),{kind:'lesson',...info});$('content').innerHTML=`<div class="session-meta"><button class="soft-button" data-view="lessons">← Список уроков</button><strong>${context.group+1}.${context.step+1} · ${STEP_NAMES[context.step]}</strong><span>цель ${lessonThreshold(context).cpm||'спокойный темп'}${lessonThreshold(context).cpm?' CPM':''} · ${lessonThreshold(context).accuracy}% · ${lessonThreshold(context).attempts} ${lessonThreshold(context).attempts===1?'попытка':'попытки подряд'}</span></div><div class="help-tip">${context.step<=2||!wordPool(settings.language,info.learned).length?'Это сочетания клавиш, а не слова. ':''}Клавиши ${esc(info.fresh.toUpperCase().split('').join(' · '))}. Возвращай пальцы на домашний ряд. Набирай без спешки: достаточно ${lessonThreshold(context).accuracy}% точности. ${lessonThreshold(context).cpm?'Цель — '+lessonThreshold(context).cpm+' CPM.':'Скорость пока не проверяется.'} Пробел завершает слово; пропущенные буквы считаются ошибками.</div>`+exerciseMarkup();bindSession()}else{session=null;context=null;if(view==='home'){$('content').innerHTML=coach.homeMarkup();disconnectHomeDemo=mountHomeDemo($('content'));}if(view==='library')$('content').innerHTML=coach.libraryMarkup();if(view==='lessons'){$('content').innerHTML=courseMarkup();disconnectLessonMap=connectLessonMap($('content'));}if(view==='stats')$('content').innerHTML=statsMarkup();if(view==='settings'){$('content').innerHTML=settingsMarkup();settingsInDialog=false;}}}
function navigate(next){if(session?.status==='running')session.pause();if(next!=='practice')forcedFocus=null;view=next;location.hash=next;render();window.scrollTo({top:0,behavior:'instant'});}
function bindSession(){
 let input=$('typingInput'),owned=session;
 const onLayout=()=>{if(session===owned)paint()};
 wordView=context.codeLines?new CodeView($('words'),owned,{lines:context.codeLines,onLayout}):new WordView($('words'),owned,{onLayout});
 input.addEventListener('focus',()=>{if(session!==owned||suppressPreviewFocus)return;if(!sessionPreview.ready){input.blur();sessionPreview.start(owned);return;}typingAudio.prime();focused=true;owned.resume();paint()});
 input.addEventListener('blur',()=>{if(session!==owned)return;typingAudio.stop();focused=false;owned.pause();paint()});
 bindTypingInput(input,{isLineEnd:index=>context.codeLines?.some(line=>line.end===index+1),getSession:()=>session===owned&&sessionPreview.ready?owned:null,getSettings:()=>settings,paint,onKey:playTypingKey,showHint:requestHint,message:text=>{if(session===owned&&$('inputMessage'))$('inputMessage').textContent=text},press:(char,feedback)=>pressKeyboard($('content'),context.layout,char,settings,feedback)});
 $('stage').addEventListener('click',()=>{if(session===owned&&owned.status!=='finished')input.focus({preventScroll:true})});paint();
}
function paint(){
 if(!session)return;if(session.status==='finished'){if(!finishedHandled)finishSession();return}if(!$('words')||!wordView)return;
 const active=focused&&session.status!=='paused';document.body.classList.toggle('session-active',active);document.body.classList.toggle('typing-focus',settings.focus&&active);
 wordView.update(settings);fitWorkspace();let rect=wordView.caretRect(),overlay=$('caretOverlay');
 if(rect&&overlay){let stageRect=$('stage').getBoundingClientRect(),underline=settings.caretStyle==='underline';overlay.style.left=(rect.left-stageRect.left)+'px';overlay.style.top=(rect.top-stageRect.top+rect.height*(underline?.91:.12))+'px';overlay.style.height=(underline?2:rect.height*.76)+'px';overlay.style.width=(settings.caretStyle==='line'?2:rect.width)+'px';overlay.style.opacity=settings.caretStyle==='block'?'.3':'1';}
 if($('sessionState'))$('sessionState').innerHTML='<i class="status-dot"></i>'+({idle:'READY',running:'TYPING',paused:'PAUSED'}[session.status]||'READY');$('stage').classList.toggle('unfocused',!focused||session.status==='paused');$('startLabel').textContent=session.status==='paused'?'Продолжить набор':'Нажмите, чтобы начать';
 let m=session.metrics(),timeMode=session.options.mode==='time',progress=timeMode?session.duration/(session.options.seconds*1000):session.word/session.words.length;
 $('exerciseProgress').style.width=Math.min(100,progress*100)+'%';$('stageCount').textContent=timeMode?formatDuration(Math.max(0,session.options.seconds*1000-session.duration)):`${session.word} / ${session.words.length}`;
 $('liveMetric').textContent=session.status==='idle'?'':`${speed(m.cpm)} ${unit()} · ${Math.round(m.accuracy)}%`;$('pauseActionLabel').textContent=session.status==='paused'?'продолжить':'пауза';
 updateKeyboard($('content'),context.layout,focused&&session.status!=='paused'?session.nextChar:null,keyboardSettings());
}
function fitWorkspace(){
 const exercise=document.querySelector('.exercise'),keyboard=exercise?.querySelector('.keyboard-wrap');if(!exercise||!keyboard)return;
 if(!document.body.classList.contains('session-active')){keyboard.style.removeProperty('width');return;}
 const available=window.innerHeight-exercise.getBoundingClientRect().top-exercise.querySelector('.editor-surface').offsetHeight-64;
 const bounds=keyboard.querySelector('svg').viewBox.baseVal;
 keyboard.style.width=Math.max(0,Math.min(960,exercise.clientWidth,available*bounds.width/bounds.height))+'px';
}
window.addEventListener('resize',()=>{if(session)paint()});
async function finishSession(){
 finishedHandled=true;document.body.classList.remove('typing-focus','session-active');fitWorkspace();wordView?.destroy();
 const owned=session,ctx=context,result={...owned.result,at:Date.now(),kind:ctx.kind,mode:ctx.testMode||'words',seconds:ctx.seconds||0,wordLimit:ctx.wordLimit||owned.words.length,materialVersion:ctx.materialVersion||1,...(ctx.kind==='test'?{numbers:!!ctx.numbers,punctuation:!!ctx.punctuation}:{})};
 let outcome;
 try{outcome=await progressStore.complete(result,ctx)}catch(error){outcome=applyCompletion(data,{...result,savedLocally:false},ctx);outcome.saved=false;}
 if(session!==owned)return;owned.result={...outcome.result,savedLocally:outcome.saved};if(ctx.kind==='practice')document.querySelector('.practice-panel')?.replaceWith(document.createRange().createContextualFragment(panelMarkup()));showResult(owned.result);if(!document.hidden&&document.hasFocus())typingAudio.finish(owned);
 if(!outcome.saved)storageError();
 else if(outcome.opened)toast(`Новая буква: ${outcome.opened.toUpperCase()}! Она появится в следующем задании.`);
}
function showResult(result){
 if($('sessionState'))$('sessionState').innerHTML='<i class="status-dot"></i>FINISHED';
 $('sessionArea').innerHTML=resultMarkup(result)+(context.kind==='activity'&&context.activity!=='code'?coach.resultExtra(result,context):'');
 updateKeyboard($('content'),context.layout,null,keyboardSettings());
 if(view==='practice')document.querySelector('.practice-panel').outerHTML=panelMarkup();
 document.querySelector('.result')?.scrollIntoView({block:'start',behavior:'instant'});
}
async function retrySave(){
 if(!session?.result)return;const owned=session,ctx=context,outcome=await progressStore.complete(owned.result,ctx).catch(()=>null);
 if(session!==owned)return;if(outcome?.saved){owned.result={...outcome.result,savedLocally:true};showResult(owned.result);toast('Результат сохранён.')}else storageError();
}
function practiceSampleMarkup(r){
 const sample=r.practiceSample;if(!sample)return '';
 const reasons={accuracy:`точность ввода и с первого раза должна быть от ${SAMPLE_ACCURACY}%`,unfinished:'допечатай и исправь все слова',speed:`скорость всего задания должна быть от ${speed(sample.floor)} ${unit()}`,measurement:'недостаточно измерений скорости'};
 const accepted=sample.accepted.map(c=>esc(c.toUpperCase())).join(' · '),observed=sample.observed||Object.keys(r.keys||{}),rejected=observed.filter(c=>!sample.accepted.includes(c));
 const title=accepted?`Засчитаны образцы: ${accepted}`:'Образцы не засчитаны';
 const explanation=sample.reasons.length?sample.reasons.map(reason=>reasons[reason]).filter(Boolean).join('; '):rejected.length?`Буквы ${rejected.map(c=>esc(c.toUpperCase())).join(' · ')} пока без образца: скорость ниже 70% цели, точность ниже ${SAMPLE_ACCURACY}% или меньше двух верных вводов с измеренным интервалом`:'';
 return `<div class="sample-status ${accepted?'sample-accepted':''}"><strong>${title}</strong>${explanation?`<p>${explanation}.</p>`:''}<small>Порог образца: ${speed(sample.floor)} ${unit()} · точность от ${SAMPLE_ACCURACY}%. Новая буква открывается после трёх образцов каждой доступной буквы и достижения полной цели ${speed(sample.goal)} ${unit()}.</small></div>`;
}
function resultMarkup(r){let failed=context.kind==='lesson'&&!r.passed,title=context.kind==='practice'?'Практика завершена':failed?r.lessonSuccess?'Закрепим шаг':'Попробуй ещё раз':'Готово!',hint=context.kind==='practice'?'Результат сохранён. Следующее задание начнётся по кнопке ниже.':context.kind==='lesson'?r.passed?'Шаг пройден. Можно переходить дальше.':r.lessonSuccess?'Хорошая попытка. Закрепи этот этап ещё один раз.':`Попробуй спокойнее: порог этого шага — ${lessonThreshold(context).accuracy}% точности ввода, с первого раза и в финальном тексте. Пройденные шаги сохраняются.`:'Результат сохранён в твою историю.',misspelled=[...new Set(r.misspelled)];return `<div class="result"><div class="result-header"><div><h2>${title}</h2><p>${r.savedLocally===false?'Результат пока доступен только на этом экране.':hint}</p></div><span class="badge">${LANGUAGES[context.lang].code} · ${context.kind==='practice'?'практика':context.kind==='lesson'?'урок':context.kind==='activity'?context.activity==='code'?esc(CODE_TRACKS[context.codeTrack].name):context.activity==='control'?'контроль':context.activity==='diagnostic'?'диагностика':context.activity==='custom'?'мой текст':'практика':context.testMode==='time'?context.seconds+'с':context.testMode==='quote'?'цитата':'слова'}</span></div>${context.kind==='test'&&context.testMode!=='quote'?`<p class="test-result-content">${testContentLabel(context)}</p>`:''}<div class="result-metrics"><div class="result-metric"><strong>${speed(r.cpm)}</strong><small>${unit()} · скорость</small></div><div class="result-metric"><strong>${Math.round(r.accuracy)}%</strong><small>точность ввода</small></div><div class="result-metric"><strong>${formatDuration(r.duration)}</strong><small>время набора</small></div></div><div class="result-detail"><span>Слова <b>${r.correctWords}</b> / <b>${r.incorrectWords}</b></span><span>Символы <b>${r.correct}</b> верно · <b>${r.incorrect+r.missed+r.extra}</b> осталось исправить</span><span>Ошибок ввода <b>${r.errors}</b>${r.omittedErrors?` · из них ${r.omittedErrors} пропущено`:""}</span><span>С первого раза <b>${Math.round(r.firstAttemptAccuracy)}%</b></span><span>Финал <b>${Math.round(r.finalAccuracy)}%</b></span><span>Исправлений <b>${r.corrections||0}</b></span><span>Помощь <b>${r.hints||0}</b></span><span title="WPM = CPM / 5">${Math.round(r.cpm)} CPM · ${(r.cpm/5).toFixed(1)} WPM</span></div>${context.kind==='practice'?practiceSampleMarkup(r):''}${r.comparable===false?'<p class="comparison-note">Была пауза: это учебная попытка. В рекорд и независимое сравнение она не входит.</p>':''}${misspelled.length?`<div class="errors-list">Слова для повторения: ${misspelled.slice(0,12).map(w=>`<span>${esc(w)}</span>`).join('')}</div>`:''}${r.savedLocally===false?'<div class="save-status" role="alert">Сохранение не удалось. Не закрывай эту страницу до повторного сохранения или скачивания копии.<div class="coach-actions"><button class="primary-button" data-action="retry-save">Повторить сохранение</button><button class="outline-button" data-coach="export">Скачать резервную копию</button></div></div>':''}<div class="result-actions">${context.activity==='code'?'<button class="primary-button" data-action="regenerate">Следующий фрагмент →</button>':context.kind==='activity'?'<button class="outline-button" data-view="library">Другой текст</button>':context.kind==='lesson'&&r.passed?'<button class="primary-button" data-action="next-lesson">Следующий шаг →</button>':'<button class="primary-button" data-action="regenerate">Следующее задание →</button>'}<button class="outline-button" data-action="repeat">Повторить текст</button>${context.kind!=='practice'&&misspelled.length?'<button class="outline-button" data-action="mistakes">Работа над ошибками</button>':''}${context.kind!=='practice'?'<button class="outline-button" data-action="result-image">Сохранить картинку</button>':''}</div><p class="result-stays">Результат останется здесь, пока ты сам не выберешь следующее действие.</p></div>`}
function courseMarkup(){return lessonMapMarkup(p().lessons,layout())}
function history(){return [...p().history,...p().tests,...(p().lessonHistory||[]),...learningFor(data,settings.language,layout()).activities.filter(r=>!['practice','lesson','test'].includes(r.activity))].sort((a,b)=>a.at-b.at)}
function chartMarkup(h){let values=h.slice(-30);if(values.length<2)return '<p class="muted" style="padding:30px 0;text-align:center;font-size:12px">График появится после двух завершённых занятий.</p>';let max=Math.max(100,...values.map(r=>r.cpm))*1.1;let points=values.map((r,i)=>`${40+i/(values.length-1)*810},${170-r.cpm/max*140}`).join(' ');return `<svg class="history-chart" viewBox="0 0 890 210" role="img" aria-label="Скорость последних ${values.length} занятий"><defs><linearGradient id="chartFill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="var(--accent)" stop-opacity=".2"/><stop offset="1" stop-color="var(--accent)" stop-opacity="0"/></linearGradient></defs>${[0,1,2,3].map(i=>`<line x1="40" x2="850" y1="${170-i*45}" y2="${170-i*45}" stroke="var(--line)"/><text x="0" y="${174-i*45}" fill="var(--muted)" font-size="10">${speed(max*i*45/140)}</text>`).join('')}<polygon points="40,170 ${points} 850,170" fill="url(#chartFill)"/><polyline points="${points}" fill="none" stroke="var(--accent)" stroke-width="2.5" stroke-linejoin="round"/>${values.map((r,i)=>`<circle cx="${40+i/(values.length-1)*810}" cy="${170-r.cpm/max*140}" r="3" fill="var(--accent)"><title>${date(r.at)} · ${speed(r.cpm)} ${unit()} · ${Math.round(r.accuracy)}%</title></circle>`).join('')}<text x="40" y="200" fill="var(--muted)" font-size="10">${date(values[0].at)}</text><text x="850" y="200" text-anchor="end" fill="var(--muted)" font-size="10">${date(values.at(-1).at)}</text></svg>`}
function statsMarkup(){
 const h=history(),avg=h.length?h.reduce((n,r)=>n+r.cpm,0)/h.length:0,acc=h.length?h.reduce((n,r)=>n+r.accuracy,0)/h.length:0,duration=h.reduce((n,r)=>n+r.duration,0),records=new Map();
 for(const r of p().tests){if(r.mode==='mistakes'||r.comparable===false)continue;const name=testRecordName(r),old=records.get(name);if(!old||r.cpm>old.cpm)records.set(name,r);}
 const unitLabel={cpm:'знаков / минуту',wpm:'слов / минуту (5 знаков)',cps:'знаков / секунду'}[settings.unit];
 const rows=items=>items.map(r=>`<tr><td>${r.kind==='practice'?'Буквы':r.kind==='lesson'?'Урок':r.kind==='activity'?esc(r.title||'Текст'):esc(testRecordName(r))}</td><td>${speed(r.cpm)} ${unit()}</td><td>${Math.round(r.accuracy)}%</td><td>${date(r.at)}</td></tr>`).join('');
 const table=items=>`<div class="table-wrap"><table><thead><tr><th>Задание</th><th>Скорость</th><th>Точность</th><th>Дата</th></tr></thead><tbody>${rows(items)}</tbody></table></div>`;
 return `<section class="stats-intro"><div><h2>Статистика</h2><p>${LANGUAGES[settings.language].code} · ${esc(LAYOUTS[layout()].name)} · занятий: ${h.length}</p></div><button class="soft-button" data-coach="metrics">Как читать цифры?</button></section><div class="compact-stats">${[['Средняя скорость',h.length?speed(avg):'—',unitLabel],['Точность',h.length?Math.round(acc)+'%':'—','опечатки учитываются после исправления'],['Набирал',formatDuration(duration),'активное время · мин:сек'],['Открыто букв',p().unlocked+' / '+[...language().alphabet].length,'в практике букв']].map(([label,value,note])=>`<article><span>${label}</span><strong>${value}</strong><small>${note}</small></article>`).join('')}</div>${h.length?`<div class="stats-overview"><section class="compact-chart"><h3>Скорость последних занятий <small>${unit()}</small></h3>${chartMarkup(h)}<p>Каждая точка — занятие. У разных заданий разная сложность.</p></section><section class="recent-sessions"><h3>Последние 5</h3>${table(h.slice(-5).reverse())}</section></div>`:`<div class="empty-stats"><span class="mode-mark">↗</span><h3>Первый результат — начало прогресса</h3><p>Заверши практику кода, букв или текста — здесь появятся скорость и точность.</p><button class="primary-button" data-view="code">Начать с кода →</button></div>`}<div class="stats-folds"><details><summary>Рекорды тестов <small>вариантов: ${records.size}</small></summary>${records.size?table([...records.values()]):'<p>Заверши тест без пауз, чтобы сохранить рекорд.</p>'}</details><details><summary>Буквы и точность клавиш</summary><p>Для новой буквы: 3 образца от 70% цели, точность от ${SAMPLE_ACCURACY}% и последняя качественная попытка от полной цели.</p><div class="compact-letter-progress">${[...language().alphabet].slice(0,p().unlocked).map(c=>{const k=p().letters[c],avg=letterSpeed(p(),c,settings.speedGoal);return `<button class="letter-progress-item" data-letter="${esc(c)}"><b>${esc(c.toUpperCase())}</b><span>${avg.count?speed(avg.cpm)+' '+unit()+' · средняя':'Нет замера'}</span><small>${Math.min(k?.samples||0,REQUIRED_SAMPLES)} / 3 образца</small></button>`}).join('')}</div>${coach.skillsMarkup()}</details><details><summary>История занятий <small>${h.length} всего</small></summary>${h.length?table(h.slice(-100).reverse()):'<p>Пока нет завершённых занятий.</p>'}${h.length>100?'<p>Показаны последние 100. Полная история хранится в резервной копии.</p>':''}</details></div><p class="compact-stats-note">Сначала удерживай точность от ${SAMPLE_ACCURACY}%, затем ускоряйся. Данные — в этом браузере; копия доступна в настройках.</p>`;
}

const switchField=(key,label,description='')=>`<div class="setting-row"><label class="setting-label" for="setting-${key}">${label}${description?`<small>${description}</small>`:''}</label><input class="switch" type="checkbox" id="setting-${key}" aria-label="${esc(label)}" data-setting="${key}" ${settings[key]?'checked':''}></div>`;
const selectField=(key,label,choices,description='')=>`<div class="setting-row"><label class="setting-label" for="setting-${key}">${label}${description?`<small>${description}</small>`:''}</label><select id="setting-${key}" aria-label="${esc(label)}" data-setting="${key}">${choices.map(([v,n])=>`<option value="${esc(v)}" ${settings[key]===v?'selected':''}>${esc(n)}</option>`).join('')}</select></div>`;
const numberField=(key,label,value,min,max,description='')=>`<div class="setting-row"><label class="setting-label" for="setting-${key}">${label}${description?`<small>${description}</small>`:''}</label><input id="setting-${key}" aria-label="${esc(label)}" type="number" min="${min}" max="${max}" step="${key==='speedGoal'&&settings.unit!=='cpm'?'0.1':'1'}" value="${value}" data-setting="${key}"></div>`;
function soundSettingsMarkup(){return `<section class="sound-settings setting-section"><div class="sound-settings-heading"><p class="eyebrow">// KEYBOARD LAB</p><h3>Настрой ощущение набора</h3><p>Выбери характер клавиш и то, что слышишь при печати.</p></div><div class="sound-modes" role="group" aria-label="Режим звука">${[['off','Без звука','Только ты и текст','○'],['normal','Обычный','Звук выбранных свитчей','⌨'],['gachi','Гачимучи','Вокальные нажатия и финалки','♂']].map(([id,name,description,mark])=>`<button class="sound-mode-card ${settings.soundMode===id?'selected':''}" data-sound-mode="${id}" aria-pressed="${settings.soundMode===id}"><span class="sound-mode-mark" aria-hidden="true">${mark}</span><strong>${name}</strong><small>${description}</small></button>`).join('')}</div><div class="sound-subheading"><h4>Свитчи клавиатуры</h4><span>MacBook Air M1 · ANSI</span></div><div class="switch-profiles" role="group" aria-label="Профиль свитчей">${Object.entries(SWITCHES).map(([id,s])=>`<button class="switch-profile ${settings.keyboardSwitch===id?'selected':''}" data-keyboard-switch="${id}" aria-pressed="${settings.keyboardSwitch===id}" style="--profile-color:${s.color}"><span class="switch-illustration" aria-hidden="true"><i></i></span><span class="switch-card-copy"><strong>${s.name}</strong><small>${s.kind}</small><span>${s.description}</span></span><span class="switch-selected" aria-hidden="true">${settings.keyboardSwitch===id?'✓':'○'}</span></button>`).join('')}</div><p class="sound-caption">${settings.soundMode==='gachi'?'При печати — мягкий вокальный звук на 100 мс с затуханием. Полные мемные реплики звучат только на финише, случайно и без повторов подряд.':'Профили меняют звук нажатия. Раскладка и размеры клавиатуры MacBook остаются привычными.'}</p>${settings.soundMode==='gachi'?`<div class="meme-sample-buttons" role="group" aria-label="Финальные реплики"><p class="sound-subheading">Финальные реплики</p>${FINAL_SAMPLE_IDS.map(id=>`<button data-meme-sample="${id}" class="meme-sample-button"><span>${MEME_CLIPS[id].name}</span><small>${MEME_CLIPS[id].seconds.toFixed(1)} с</small></button>`).join('')}</div>`:''}<div class="sound-volume-row"><label for="setting-soundVolume">Громкость <output id="soundVolumeValue" for="setting-soundVolume">${settings.soundVolume}%</output></label><input type="range" id="setting-soundVolume" data-setting="soundVolume" min="0" max="100" step="1" value="${settings.soundVolume}" aria-label="Громкость звука"></div><div class="sound-preview-actions"><button class="primary-button" data-action="preview-sound" ${settings.soundMode==='off'?'disabled':''}>${icon('play')} ${settings.soundMode==='gachi'?'Нажатие · 100 мс':'Послушать'}</button>${settings.soundMode==='gachi'?'<button class="outline-button" data-action="preview-finish-sound">Случайная финалка</button>':''}<span id="soundPreviewStatus" role="status" aria-live="polite">${settings.soundMode==='off'?'Звук выключен':settings.soundVolume===0?'Без звука · громкость 0%':'Проверь громкость перед началом'}</span></div></section>`}
async function previewSound(id){const status=$('soundPreviewStatus');if(status)status.textContent='Загружаем и воспроизводим…';const result=await typingAudio.preview(id);if(status?.isConnected)status.textContent=result.ok?(result.name?result.name+' · '+result.milliseconds+' мс':'Можно печатать'):result.message||'Предпрослушивание остановлено';}
function settingsMarkup(){let tabs=[['practice','Практика'],['appearance','Внешний вид'],['behavior','Поведение'],['sound','Звук'],['data','Данные']];return `<div class="settings-tabs" role="group" aria-label="Раздел настроек">${tabs.map(([v,n])=>`<button class="${settingsTab===v?'active':''}" data-settings-tab="${v}">${n}</button>`).join('')}</div>${settingsTab==='sound'?soundSettingsMarkup():settingsTab==='data'?coach.dataMarkup():settingsTab==='practice'?`<section class="setting-section"><h3>Основные</h3>${numberField('fontSize','Размер текста',settings.fontSize,18,48,'От 18 до 48 px. Практика, тесты, уроки и код.')}<div class="settings-preview">const speed = 250;</div>${selectField('language','Язык упражнений',Object.entries(LANGUAGES).map(([id,l])=>[id,l.name]),'Язык интерфейса — русский. У каждого языка и раскладки отдельный профиль.')}<div class="setting-row"><label class="setting-label" for="setting-layout">Раскладка клавиатуры<small>Выбери ту же раскладку, которая включена на компьютере.</small></label><select id="setting-layout" aria-label="Раскладка клавиатуры" data-setting="layout">${availableLayouts(settings.language).map(v=>`<option value="${esc(v)}" ${layout()===v?'selected':''}>${esc(LAYOUTS[v].name)}</option>`).join('')}</select></div>${selectField('unit','Единицы скорости',[['cpm','CPM'],['wpm','WPM'],['cps','CPS']],'CPM — знаки в минуту. WPM = CPM ÷ 5. CPS = CPM ÷ 60.')}${numberField('speedGoal','Целевая скорость · '+unit(),speed(settings.speedGoal),settings.unit==='cpm'?1:.1,settings.unit==='cpm'?3000:600,`Образец: от 70% цели, точность от ${SAMPLE_ACCURACY}%, весь текст исправлен. Новая буква: три образца для каждой доступной буквы и её скорость от 100% цели.`)}</section>`:settingsTab==='appearance'?`<section class="setting-section"><h3>Текст и курсор</h3><p class="storage-note">Текущая строка остаётся на одной высоте. При переходе на следующую текст поднимается; внутри строки пробел перемещает только курсор.</p>${numberField('letterSpacing','Расстояние между символами',settings.letterSpacing||0,0,5)}${selectField('caretStyle','Вид курсора',[['line','Линия'],['block','Блок'],['underline','Подчёркивание']])}${switchField('reverse','Инверсия цвета текста','Меняет оттенки набранных и ещё не набранных символов.')}<div class="settings-preview"><span>Печатай</span><i></i> спокойно и уверенно.</div></section><section class="setting-section"><h3>Клавиатура</h3>${switchField('keyboard','Показывать клавиатуру')}${switchField('hands','Показывать руки','Подсказка по стандартной карте пальцев.')}${switchField('handsMotion','Движение рук','Выключи, если предпочитаешь спокойную статичную подсказку.')}${selectField('hintMode','Помощь',[['always','Всегда'],['request','По запросу · F1'],['off','Скрыта · F1 для помощи']],'Запросы учитываются отдельно от ошибок.')}<div class="setting-row"><span class="setting-label">Цветовая тема</span><button class="outline-button" data-action="themes">Выбрать тему</button></div></section>`:`<section class="setting-section"><h3>Набор текста</h3>${switchField('spaceToFinish','Пробел для завершения','В конце последнего слова нажми пробел. Если выключено — упражнение завершится на последней букве.')}${switchField('noWayBack','Нет пути назад','Запрещает удалять символы и возвращаться к предыдущим словам.')}${switchField('focus','Режим фокуса','Во время набора всё окружение сильно размывается и почти исчезает. Текст, руки и клавиатура остаются чёткими. Esc возвращает интерфейс.')}${switchField('hideExtra','Скрывать лишние символы','Ошибки за границей слова учитываются даже при скрытии.')}${switchField('inputVisible','Показывать поле ввода','Отдельное поле для текущего слова.')}<div class="help-tip">Исправленная ошибка остаётся в статистике. Backspace удаляет символ, Ctrl / ⌘ + Backspace — слово. Esc ставит занятие на паузу.</div></section>`}<p class="storage-note">Изменения сохраняются автоматически.</p>`}
function openDialog(title,body,extra=''){sessionPreview.cancel();typingAudio.stop();session?.pause();document.body.classList.remove('typing-focus','session-active');$('dialog').innerHTML=`<div class="dialog-header"><h2>${title}</h2><button data-action="close-dialog" aria-label="Закрыть">${icon('close')}</button></div>${body}${extra}`;$('dialog').showModal()}
function openSettings(tab='practice'){settingsTab=tab;settingsInDialog=true;resetAfterSettings=false;openDialog('Настройки',settingsMarkup());}
function closeDialog(){if(onboarding.active){onboarding.dismiss();return;}let wasSettings=settingsInDialog;$('dialog').close();settingsInDialog=false;if(resetAfterSettings){resetAfterSettings=false;if(view==='lesson')view='lessons';if(view==='activity'){view='home';activityPayload=null;}render()}else if(wasSettings&&session){const panel=$('content').querySelector('.practice-panel');if(panel&&view==='practice')panel.outerHTML=panelMarkup();paint()} }
function changeSetting(el){let key=el.dataset.setting,value=el.type==='checkbox'?el.checked:el.value;if(el.type==='number'||el.type==='range'){value=Number(value);if(!Number.isFinite(value)||value<Number(el.min)||value>Number(el.max)){el.value=key==='speedGoal'?speed(settings.speedGoal):settings[key];toast('Укажи значение от '+el.min+' до '+el.max+'.');return}}
 if(key==='layout'){if(!availableLayouts(settings.language).includes(value))return;settings.layouts[settings.language]=value;resetAfterSettings=true}else if(key==='speedGoal'){settings.speedGoal=Math.round(value*(settings.unit==='wpm'?5:settings.unit==='cps'?60:1))}else{settings[key]=value;if(key==='language'){if(!availableLayouts(value).includes(settings.layouts[value]))settings.layouts[value]=LANGUAGES[value].layout;forcedFocus=null;resetAfterSettings=true}}
 if(session&&session.status!=='finished'&&['spaceToFinish','noWayBack'].includes(key))resetAfterSettings=true;persist();applySettings();if(key==='soundMode')typingAudio.prime();if(key==='soundVolume'){if($('soundVolumeValue'))$('soundVolumeValue').textContent=value+'%';if($('soundPreviewStatus'))$('soundPreviewStatus').textContent=value===0?'Без звука · громкость 0%':'Громкость сохранена';}if(['dailyType','language','unit','wordsView','soundMode','keyboardSwitch'].includes(key)){if(settingsInDialog)$('dialog').innerHTML=`<div class="dialog-header"><h2>Настройки</h2><button data-action="close-dialog" aria-label="Закрыть">${icon('close')}</button></div>`+settingsMarkup();else $('content').innerHTML=settingsMarkup()}if(!settingsInDialog&&view==='settings')header();if(!resetAfterSettings&&session&&session.status!=='finished'){let input=$('typingInput');input?.classList.toggle('visible',settings.inputVisible);$('words')?.classList.toggle('tape',settings.wordsView==='tape');paint()} }
function themes(){settingsInDialog=false;openDialog('Цвета',`<div class="theme-options">${[['dark','Night Editor','#101317','#70e4b4','#a9a6ff','#ff7f8d'],['light','Day Editor','#f6f8fa','#087956','#635bc8','#bc4057'],['warm','Тёплая','#f1eee7','#9d733e','#8e9373','#b66e64']].map(([id,name,bg,a,b,c])=>`<button class="theme-option ${settings.theme===id?'active':''}" data-theme="${id}"><div class="theme-swatch" style="background:${bg}"><i style="background:${a}"></i><i style="background:${b}"></i><i style="background:${c}"></i></div>${name}<small>${settings.theme===id?'Выбрана':'Нажми, чтобы применить'}</small></button>`).join('')}</div>`)}
const guide=[['Практика подстраивается под тебя','Начни с пяти доступных букв. В заданиях используются только знакомые клавиши, а новые открываются постепенно.','О Е А И Н'],['Буква, которой нужно внимание','Тренажёр выбирает новую или самую слабую букву и включает её примерно в половину слов; остальные закрепляют знакомые клавиши. Можно выбрать доступную букву вручную.','E E E'],['Как открываются новые буквы',`Образец засчитывается от 70% цели при точности ввода и с первого раза от ${SAMPLE_ACCURACY}%. Все слова должны быть допечатаны и исправлены. Нужны минимум два верных ввода буквы и измеренный интервал. Скорость буквы не может быть выше скорости всего задания. Для новой буквы: по три образца каждой доступной буквы и её последняя качественная попытка от 100% цели.`,'5 → +1'],['Смотри на экран','Подсветка клавиши и движение пальца показывают, чем нажать. После нажатия возвращай пальцы на домашний ряд. На А и О (F и J) есть выступы.','Ф Ы В А · О Л Д Ж'],['Ошибки можно исправить','Используй Backspace для символа и Ctrl / ⌘ + Backspace для слова. Ошибка останется в статистике — так ты увидишь, над чем работать.','←'],['Занимайся понемногу каждый день',`Несколько коротких упражнений помогают сохранять ровный ритм. Удерживай точность от ${SAMPLE_ACCURACY}% и повышай скорость постепенно.`,'10–15 мин']];
function showGuide(){let [title,text,illustration]=guide[guideStep];if(guideStep===0)illustration=language().alphabet.slice(0,5).toUpperCase().split('').join(' · ');if(guideStep===3){let home=LAYOUTS[layout()].rows[1];illustration=home.slice(0,4).toUpperCase()+' · '+home.slice(6,10).toUpperCase();text='Подсветка клавиши и движение пальца показывают, чем нажать. Возвращай пальцы на домашний ряд. На клавишах указательных пальцев есть выступы: для выбранной раскладки это '+home[3].toUpperCase()+' и '+home[6].toUpperCase()+'.'}settingsInDialog=false;openDialog('Руководство по практике',`<div class="guide-count">ШАГ ${guideStep+1} / ${guide.length}</div><h2>${title}</h2><div class="guide-illustration">${esc(illustration)}</div><div class="help-copy"><p>${text}</p></div>`,`<div class="dialog-footer"><button class="outline-button" data-guide="back" ${guideStep===0?'disabled':''}>← Назад</button><button class="primary-button" data-guide="next">${guideStep===guide.length-1?'Начать практику':'Дальше →'}</button></div>`)}
function help(){settingsInDialog=false;openDialog('Как печатать быстрее и точнее',`<div class="help-copy"><h3>Поставь руки на домашний ряд</h3><p>В русской раскладке левая рука лежит на <b>Ф Ы В А</b>, правая — на <b>О Л Д Ж</b>. В английской — <b>A S D F</b> и <b>J K L ;</b>. Указательные пальцы находят выступы на А и О (F и J), большие нажимают пробел.</p><p>Для выбранной раскладки ${esc(LAYOUTS[layout()].name)} домашний ряд: <b>${esc(LAYOUTS[layout()].rows[1].slice(0,4).toUpperCase().split('').join(' '))}</b> слева и <b>${esc(LAYOUTS[layout()].rows[1].slice(6,10).toUpperCase().split('').join(' '))}</b> справа.</p><h3>Скорость для программиста</h3><p><b>Код</b> тренирует набор конструкций, скобок и операторов. <b>Тексты</b> помогают держать ритм, работать с Shift, цифрами и знаками. <b>Практика</b> укрепляет отдельные буквы. Начни с удобного темпа и постепенно ускоряйся.</p><h3>Выбери способ обучения</h3><p><b>Уроки</b> знакомят с клавишами по шагам. <b>Практика</b> подбирает слова под слабые буквы. <b>Тест</b> измеряет навык по времени, словам или цитате. <b>Статистика</b> показывает историю и личные рекорды.</p><h3>Не торопись</h3><p>Смотри на экран и пользуйся подсказками рук. Расслабь плечи и кисти. Если устаёшь — сделай перерыв. Точность ${SAMPLE_ACCURACY}% и выше важнее высокой скорости.</p><h3>Клавиши управления</h3><p><b>Пробел</b> — следующее слово. <b>Backspace</b> — исправить символ. <b>Ctrl / ⌘ + Backspace</b> — удалить слово. <b>Esc</b> — пауза. После упражнения результат остаётся открытым. Выбери кнопку под ним; с клавиатуры используй Tab и Enter.</p><div class="coach-actions"><button class="primary-button" data-action="onboarding">Пройти обучение →</button><button class="outline-button" data-action="guide">Правила практики</button></div></div>`)}
function letterDialog(letter){let index=[...language().alphabet].indexOf(letter),open=index<p().unlocked,key=p().letters[letter],avg=letterSpeed(p(),letter,settings.speedGoal);settingsInDialog=false;openDialog('Буква '+esc(letter.toUpperCase()),`<div class="letter-stage">${esc(letter.toUpperCase())}</div><div class="letter-detail"><div><b>${avg.count?speed(avg.cpm):'—'}</b><small>средняя · ${unit()} · ${avg.count}/5 попыток</small></div><div><b>${key?speed(key.topCPM):'—'}</b><small>лучшая качественная · ${unit()}</small></div><div><b>${avg.percent.toFixed(0)}%</b><small>от цели скорости</small></div></div><div class="help-copy"><p>Цвет и шкала показывают среднюю скорость последних пяти завершённых упражнений с этой буквой. Пока попыток меньше пяти, берём все доступные. До 60% цели цвет красный, затем постепенно меняется до зелёного при 100%. Самая слабая буква — доступная буква с самой низкой средней скоростью среди измеренных. Ошибочные попытки тоже учитываются; одна и та же попытка не считается дважды.</p><p>${open?`Качественных образцов: ${Math.min(key?.samples||0,REQUIRED_SAMPLES)} / ${REQUIRED_SAMPLES}. Цель: ${speed(settings.speedGoal)} ${unit()}. Образец: от ${speed(settings.speedGoal*.7)} ${unit()}, точность от ${SAMPLE_ACCURACY}%, все слова исправлены.`:'Буква пока закрыта.'} Для следующей буквы нужны три качественных образца каждой доступной буквы и полная цель скорости в последней качественной попытке.</p></div>${open?`<button class="primary-button" data-focus-letter="${esc(letter)}">Тренировать эту букву</button>`:''}`)}
function customTest(){settingsInDialog=false;openDialog(settings.testMode==='time'?'Продолжительность теста':'Количество слов',`<label class="custom-label" for="customValue">${settings.testMode==='time'?'Секунды или запись с h, m, s — например 1m 30s':'Целое число от 1 до 10000'}</label><input class="custom-input" id="customValue" value="${settings.testMode==='time'?settings.testTime:settings.testWords}" autocomplete="off"><p class="validation-error" id="customError" role="alert"></p><div class="dialog-footer"><span></span><button class="primary-button" data-action="save-custom">Применить</button></div>`)}
function saveCustom(){let raw=$('customValue').value.trim(),value;if(settings.testMode==='time'){if(/^\d+$/.test(raw))value=Number(raw);else if(/^(?:\d+\s*[hms]\s*)+$/i.test(raw)){value=0;for(let m of raw.matchAll(/(\d+)\s*([hms])/gi))value+=Number(m[1])*({h:3600,m:60,s:1})[m[2].toLowerCase()]}if(!Number.isInteger(value)||value<1||value>14400){$('customError').textContent='Укажи время от 1 секунды до 4 часов.';return}settings.testTime=value}else{value=Number(raw);if(!Number.isInteger(value)||value<1||value>10000){$('customError').textContent='Укажи целое число от 1 до 10000.';return}settings.testWords=value}persist();$('dialog').close();render()}
function repeat(){if(!session)return;let words=[...session.words],ctx={...context};if(ctx.activity==='code'){makeSession(words,ctx);$('content').innerHTML=codeControls()+exerciseMarkup();bindSession();$('typingInput').focus({preventScroll:true});return;}if(ctx.kind==='activity'){if(ctx.activity==='control')ctx.activity='review';startActivity(words,ctx);$('typingInput').focus({preventScroll:true});return;}makeSession(words,ctx);if(view==='practice')$('content').innerHTML=panelMarkup()+exerciseMarkup();else if(view==='test')$('content').innerHTML=testControls()+exerciseMarkup();else $('content').innerHTML=`<div class="session-meta"><button class="soft-button" data-view="lessons">← Список уроков</button><strong>${ctx.group+1}.${ctx.step+1} · ${STEP_NAMES[ctx.step]}</strong><span>цель ${lessonThreshold(context).cpm||'спокойный темп'}${lessonThreshold(context).cpm?' CPM':''} · ${lessonThreshold(context).accuracy}% · ${lessonThreshold(context).attempts} ${lessonThreshold(context).attempts===1?'попытка':'попытки подряд'}</span></div>`+exerciseMarkup();bindSession();$('typingInput').focus({preventScroll:true})}
function nextLesson(){navigate('lessons');const node=[...document.querySelectorAll('[aria-current="step"]')].find(el=>el.getClientRects().length);node?.scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});toast(node?'Следующий этап открыт. Продолжи путь на карте.':'Курс пройден! Продолжай совершенствоваться в практике.')}
function mistakes(){if(!session?.result?.misspelled.length)return;let words=[...session.result.misspelled];if(context.kind!=='test'){startActivity(words,{activity:'mistakes',title:'Короткая работа над ошибками',reason:'Слова из последней попытки. Каждая ошибка добавляет повтор; после коррекции вернись к новому контексту.'});$('typingInput').focus({preventScroll:true});return;}makeSession(words,{kind:'test',mode:'words',testMode:'mistakes',wordLimit:words.length,numbers:context.numbers,punctuation:context.punctuation});$('content').innerHTML=`<div class="session-meta"><strong>Работа над ошибками · ${words.length} ${words.length%10===1&&words.length%100!==11?'слово':words.length%10>=2&&words.length%10<=4&&(words.length%100<12||words.length%100>14)?'слова':'слов'}</strong><button class="soft-button" data-view="test">← Обычный тест</button></div>`+exerciseMarkup();bindSession();$('typingInput').focus({preventScroll:true})}
function downloadResult(){if(!session?.result)return;let r=session.result,c=document.createElement('canvas');c.width=1200;c.height=680;let g=c.getContext('2d');g.fillStyle=settings.theme==='dark'?'#101317':settings.theme==='light'?'#f6f8fa':'#f3efe7';g.fillRect(0,0,c.width,c.height);g.fillStyle=settings.theme==='dark'?'#70e4b4':'#087956';g.font='bold 35px monospace';g.fillText('Десять пальцев',70,90);g.fillStyle=settings.theme==='dark'?'#dce5ee':'#223246';g.font='22px monospace';g.fillText(language().name+' · '+date(Date.now()),70,145);[[speed(r.cpm),unit()],[(Math.round(r.accuracy)+'%'),'точность'],[formatDuration(r.duration),'время']].forEach(([v,n],i)=>{g.font='68px monospace';g.fillText(v,70+i*370,310);g.font='22px monospace';g.fillText(n,70+i*370,355)});g.font='20px monospace';g.fillText(`Правильных символов: ${r.correct}   Ошибочных позиций: ${r.errors}`,70,460);g.fillText('Регулярная практика. Уверенный навык.',70,570);c.toBlob(blob=>{let url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='typing-result.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)})}
$('sidebar').addEventListener('click',handleClick);$('header').addEventListener('click',handleClick);$('content').addEventListener('pointerdown',e=>{if(e.target.closest('button[data-action="pause"]'))e.preventDefault()});$('content').addEventListener('click',handleClick);$('dialog').addEventListener('click',handleClick);$('content').addEventListener('change',e=>{if(e.target.dataset.setting)changeSetting(e.target);else coach.handleChange(e.target)});$('content').addEventListener('input',e=>coach.rememberDraft(e.target));$('dialog').addEventListener('change',e=>{if(e.target.dataset.setting)changeSetting(e.target);else coach.handleChange(e.target)});$('dialog').addEventListener('cancel',e=>{e.preventDefault();closeDialog()});$('dialog').addEventListener('click',e=>{if(e.target===$('dialog')){let r=$('dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog()}});
function handleClick(e){let b=e.target.closest('button');if(!b||b.disabled)return;if(onboarding.handleClick(b))return;if(b.dataset.memeSample){previewSound(b.dataset.memeSample);return;}if(b.dataset.soundMode){changeSetting({dataset:{setting:'soundMode'},type:'select-one',value:b.dataset.soundMode});return;}if(b.dataset.keyboardSwitch){changeSetting({dataset:{setting:'keyboardSwitch'},type:'select-one',value:b.dataset.keyboardSwitch});return;}if(b.dataset.trainingLanguage){selectTrainingLanguage(b.dataset.trainingLanguage);return}if(b.dataset.startLanguage){selectTrainingLanguage(b.dataset.startLanguage,true);return}if(b.dataset.codeVolume&&CODE_VOLUMES[b.dataset.codeVolume]){settings.codeVolume=b.dataset.codeVolume;persist();render();return;}if(b.dataset.codeTrack&&CODE_TRACKS[b.dataset.codeTrack]){settings.codeTrack=b.dataset.codeTrack;persist();render();return}if(coach.handleClick(b))return;if(b.dataset.view){navigate(b.dataset.view);return}if(b.dataset.group!==undefined){const node=lessonRoute(p().lessons,layout()).groups[Number(b.dataset.group)]?.steps[Number(b.dataset.step)];if(!node||node.status==='locked'){toast('Сначала пройди выделенный этап.');return;}context={group:Number(b.dataset.group),step:Number(b.dataset.step)};view='lesson';location.hash='lessons';render();return}if(b.dataset.letter){letterDialog(b.dataset.letter);return}if(b.dataset.focusLetter){forcedFocus=b.dataset.focusLetter;$('dialog').close();view='practice';location.hash='practice';render();$('typingInput').focus({preventScroll:true});return}if(b.dataset.testMode){settings.testMode=b.dataset.testMode;persist();render();return}if(b.dataset.testAmount){settings[settings.testMode==='time'?'testTime':'testWords']=Number(b.dataset.testAmount);persist();render();return}if(b.dataset.settingsTab){settingsTab=b.dataset.settingsTab;if(settingsInDialog)$('dialog').innerHTML=`<div class="dialog-header"><h2>Настройки</h2><button data-action="close-dialog" aria-label="Закрыть">${icon('close')}</button></div>`+settingsMarkup();else $('content').innerHTML=settingsMarkup();return}if(b.dataset.theme){settings.theme=b.dataset.theme;persist();applySettings();themes();return}if(b.dataset.guide){if(b.dataset.guide==='back')guideStep=Math.max(0,guideStep-1);else if(guideStep<guide.length-1)guideStep++;else{data.guideSeen=true;persist();closeDialog();$('typingInput')?.focus({preventScroll:true});return}showGuide();return}
 switch(b.dataset.action){case'enable-sound':settings.soundMode='normal';if(!settings.soundVolume)settings.soundVolume=35;persist();typingAudio.sync();typingAudio.preview().then(result=>toast(result.ok?'Звук включён. Громкость и свитчи — в настройках звука.':result.message||'Нажми «Послушать» в настройках звука.'));paint();break;case'exit-focus':session?.pause();$('typingInput')?.blur();focused=false;paint();break;case'sound-settings':openSettings('sound');break;case'preview-sound':previewSound('tap');break;case'preview-finish-sound':previewSound('final');break;case'retry-save':retrySave();break;case'hint':requestHint();break;case'close-dialog':closeDialog();break;case'practice-settings':case'language':openSettings('practice');break;case'help':help();break;case'guide':guideStep=0;showGuide();break;case'themes':themes();break;case'test-plain':settings.numbers=false;settings.punctuation=false;persist();render();break;case'numbers':settings.numbers=!settings.numbers;persist();render();break;case'punctuation':settings.punctuation=!settings.punctuation;persist();render();break;case'custom-test':customTest();break;case'save-custom':saveCustom();break;case'repeat':repeat();break;case'regenerate':if(view==='activity'){if(!coach.newText(activityPayload?.ctx.activity))navigate('library');$('typingInput')?.focus({preventScroll:true});break;}forcedFocus=null;render();$('typingInput')?.focus({preventScroll:true});break;case'pause':if(session?.status==='paused'){$('typingInput').focus({preventScroll:true})}else if(session){session.pause();$('typingInput')?.blur();paint()}break;case'next-lesson':nextLesson();break;case'mistakes':mistakes();break;case'result-image':downloadResult();break;}
}
window.addEventListener('storage',e=>{if(e.key!==STORAGE_KEY||!e.newValue)return;try{const remote=progressStore.read();data=mergePreferences(progressStore.baseline,data,remote);settings=data.settings;settings.wordsView='rows';applySettings();if(!session)render();}catch{storageError();}});window.addEventListener('blur',()=>{sessionPreview.cancel();typingAudio.stop();if(session){focused=false;session.pause();paint()}});window.addEventListener('focus',()=>{if(session&&sessionPreview.ready&&document.activeElement===$('typingInput')){focused=true;session.resume();paint()}});document.addEventListener('visibilitychange',()=>{if(document.hidden){sessionPreview.cancel();typingAudio.stop();}if(document.hidden&&session){session.pause();focused=false;paint()}else if(session&&sessionPreview.ready&&document.activeElement===$('typingInput')){focused=true;session.resume();paint()}});window.addEventListener('hashchange',()=>{let next=location.hash.slice(1);if(next==='plan')next='home';if(['home','library','practice','code','lessons','test','stats','settings'].includes(next)&&next!==view&&!(view==='lesson'&&next==='lessons')){view=next;forcedFocus=null;render();window.scrollTo({top:0,behavior:'instant'});}});setInterval(()=>{if(session?.status==='running'){session.tick();paint()}},250);
if(location.hash==='#plan')window.history.replaceState(null,'','#home');
view=['home','library','practice','code','lessons','test','stats','settings'].includes(location.hash.slice(1))?location.hash.slice(1):'home';render();onboarding.maybeStart();if(data.recoveryNeeded)toast('Сохранённые данные не удалось прочитать. Они не перезаписаны: восстанови резервную копию в настройках данных.');
